def where(finding):
    path = finding.get("path")
    return f"{path}:{finding['line']}" if path else "this input"


def guidance_for(finding):
    """{fix, fix_ar, verify, verify_ar} for a finding dict, or None when the rule has no entry."""
    from .checks.source_code import language
    rule = finding["rule"]
    place = where(finding)
    if rule in SOURCE:
        lead, lead_ar, examples, verify, verify_ar = SOURCE[rule]
        code = examples.get(language(finding.get("path") or ""))
        fix = lead + (f"\nExample:\n{code}" if code else "")
        fix_ar = lead_ar + (f"\nمثال:\n{code}" if code else "")
    elif rule in GUIDE:
        fix, fix_ar, verify, verify_ar = GUIDE[rule]
    else:
        return None
    return {"fix": fix.replace("{where}", place), "fix_ar": fix_ar.replace("{where}", place),
            "verify": verify.replace("{where}", place), "verify_ar": verify_ar.replace("{where}", place)}


def attach(findings):
    for item in findings:
        item_guidance = guidance_for(item)
        if item_guidance:
            item["guidance"] = item_guidance
    return findings
